using System.Net;using System.Net.Http.Headers;using System.Net.Http.Json;using System.Text;using Xunit;
namespace AiCare.Tests;
[Collection("Postgres regression")]
public sealed class IntegrationImportPreviewRegressionTests(PostgresRegressionFactory factory):IClassFixture<PostgresRegressionFactory>
{
 [Fact]public async Task AdminCanMapValidateDetectDuplicatesAndDownloadErrors(){await factory.EnsureClinicalSeedAsync();var client=factory.CreateClient();var login=await client.PostAsJsonAsync("/api/auth/login",new{userName="admin",password="Admin123!",mfaCode=(string?)null});login.EnsureSuccessStatusCode();client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",(await login.Content.ReadFromJsonAsync<Login>())!.Token);var csv="Name,DOB,Phone\nRegression Person,1980-01-01,07000000000\nNew Person,not-a-date,07000000001\nValid Person,1990-02-03,07000000002\n";using var content=new MultipartFormDataContent();content.Add(new ByteArrayContent(Encoding.UTF8.GetBytes(csv)){Headers={ContentType=new MediaTypeHeaderValue("text/csv")}},"file","people.csv");content.Add(new StringContent("People"),"resourceType");content.Add(new StringContent("{\"Name\":\"fullName\",\"DOB\":\"dateOfBirth\",\"Phone\":\"phoneNumber\"}"),"mappingJson");var response=await client.PostAsync("/api/phase1/integrations/imports/preview",content);Assert.Equal(HttpStatusCode.OK,response.StatusCode);var preview=(await response.Content.ReadFromJsonAsync<Preview>())!;Assert.Equal(3,preview.TotalRows);Assert.Equal(2,preview.ValidRows);Assert.Equal(1,preview.InvalidRows);Assert.Equal(1,preview.DuplicateRows);var errors=await client.GetStringAsync($"/api/phase1/integrations/imports/{preview.Id}/errors.csv");Assert.Contains("dateOfBirth is invalid",errors);}
 private sealed record Login(string Token);private sealed record Preview(Guid Id,int TotalRows,int ValidRows,int InvalidRows,int DuplicateRows);
}
